public int majorityElement(int[] nums) {
        int a = nums[0];
        int times = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] == a) {
                times++;
            } else {
                times--;
            }
            if (times == 0) {
                a = nums[i];
                times = 1;
            }
        }
        return a;
    }

