public int majorityElement(int[] nums) {

        int cnt = 1;
        int cur = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (cur != nums[i]) {
                cnt--;
                if (cnt <= 0) {
                    cur = nums[i];
                    cnt = 1;
                }
            } else {
                cnt++;
            }
        }
        return cur;
    }
